//! Reproducible third-party notices from the locked dependency graph.
//!
//! Inputs are Cargo's locked metadata and the crate sources Cargo already unpacked; there is
//! no network access of its own, no extra tool and no timestamp or host path in the output.
use crate::{Project, Result, capture};
use serde_json::Value;
use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};

/// Root-level asset published next to the binary; generated by `cargo xtask notices`.
pub(crate) const FILE: &str = "THIRD_PARTY_NOTICES";
/// Product license, published next to the binary.
pub(crate) const LICENSE: &str = "LICENSE";
/// Per-file bound for license texts; larger files indicate something other than a license.
const MAX_TEXT_BYTES: u64 = 256 * 1024;
/// Prefixes (upper-cased) of top-level crate files that carry license or notice terms.
const NAME_PREFIXES: [&str; 6] = [
    "LICENSE",
    "LICENCE",
    "COPYING",
    "UNLICENSE",
    "NOTICE",
    "COPYRIGHT",
];
/// Canonical Apache-2.0 text for the crates that declare it without shipping a license file.
const APACHE_2_0: &str = include_str!("../notices/Apache-2.0.txt");
/// Reviewed exceptions: exact crate, exact version and exact declared license only. A new
/// version without a license file fails the gate until it is reviewed again.
const FALLBACKS: &[(&str, &str, &str, &str)] = &[(
    "rmcp",
    "3.4.0",
    "Apache-2.0",
    "The published crate ships no license file; its manifest declares Apache-2.0. The canonical Apache License 2.0 text is included below.",
)];
/// Native code compiled into the binary that is not a Rust crate of its own.
const NATIVE_NOTES: &[(&str, &str)] = &[(
    "libsqlite3-sys",
    "libsqlite3-sys bundles the SQLite C amalgamation, which is in the public domain (https://sqlite.org/copyright.html). The crate itself is covered by its license text below.",
)];

/// One locked registry package that can end up in the executable.
#[derive(Debug, PartialEq, Eq)]
struct Package {
    name: String,
    version: String,
    license: String,
    /// Unpacked crate directory.
    dir: PathBuf,
    /// `license-file` from the manifest, relative to `dir`.
    license_file: Option<String>,
}

/// Select registry packages reachable from the root through normal (non-dev, non-build)
/// dependency edges. Proc-macro crates are normal edges and stay in the set on purpose:
/// over-inclusion is safe, omission is not. Workspace crates are covered by `LICENSE`.
fn reachable(metadata: &Value) -> Result<Vec<Package>> {
    let root = metadata["resolve"]["root"]
        .as_str()
        .ok_or("metadata has no resolved root package")?;
    let nodes: BTreeMap<&str, &Value> = metadata["resolve"]["nodes"]
        .as_array()
        .ok_or("metadata has no resolve graph")?
        .iter()
        .filter_map(|node| Some((node["id"].as_str()?, node)))
        .collect();
    let packages: BTreeMap<&str, &Value> = metadata["packages"]
        .as_array()
        .ok_or("metadata has no packages")?
        .iter()
        .filter_map(|package| Some((package["id"].as_str()?, package)))
        .collect();
    let mut seen = BTreeSet::new();
    let mut pending = vec![root];
    while let Some(id) = pending.pop() {
        if !seen.insert(id) {
            continue;
        }
        let node = nodes.get(id).ok_or("dependency node missing")?;
        for dependency in node["deps"].as_array().into_iter().flatten() {
            let normal = dependency["dep_kinds"]
                .as_array()
                .is_some_and(|kinds| kinds.iter().any(|kind| kind["kind"].is_null()));
            if normal {
                pending.push(dependency["pkg"].as_str().ok_or("dependency id missing")?);
            }
        }
    }
    let mut result = Vec::new();
    for id in seen {
        let package = packages.get(id).ok_or("reachable package missing")?;
        match package["source"].as_str() {
            None => continue,
            Some(source) if source.starts_with("registry+") => {}
            Some(_) => return Err("unsupported dependency source; review notices".into()),
        }
        let field = |key: &str| {
            package[key]
                .as_str()
                .map(str::to_owned)
                .ok_or(format!("package {id} lacks {key}"))
        };
        let manifest = PathBuf::from(field("manifest_path")?);
        result.push(Package {
            name: field("name")?,
            version: field("version")?,
            license: package["license"]
                .as_str()
                .map(str::to_owned)
                .ok_or(format!("package {id} declares no license"))?,
            dir: manifest
                .parent()
                .ok_or("manifest has no directory")?
                .to_path_buf(),
            license_file: package["license_file"].as_str().map(str::to_owned),
        });
    }
    result.sort_by(|a, b| (&a.name, &a.version).cmp(&(&b.name, &b.version)));
    Ok(result)
}

/// Read one bounded UTF-8 license text with normalized line endings and no trailing blanks.
fn read_text(path: &Path) -> Result<String> {
    let metadata = fs::symlink_metadata(path)?;
    if !metadata.file_type().is_file() || metadata.len() > MAX_TEXT_BYTES {
        return Err(format!(
            "license file is not a bounded regular file: {}",
            path.display()
        )
        .into());
    }
    let text = String::from_utf8(fs::read(path)?)
        .map_err(|_| format!("license file is not UTF-8: {}", path.display()))?;
    Ok(format!("{}\n", text.replace("\r\n", "\n").trim_end()))
}

/// Collect the license and notice texts of one package, preferring shipped files.
/// Returns file-name-ordered texts, or the reviewed fallback when the crate ships none.
fn texts(package: &Package) -> Result<Vec<String>> {
    let mut names = BTreeSet::new();
    for entry in fs::read_dir(&package.dir)? {
        let entry = entry?;
        let name = entry.file_name().to_string_lossy().into_owned();
        let upper = name.to_ascii_uppercase();
        if entry.file_type()?.is_file() && NAME_PREFIXES.iter().any(|p| upper.starts_with(p)) {
            names.insert(name);
        }
    }
    if let Some(file) = &package.license_file {
        let relative = Path::new(file);
        if relative
            .components()
            .any(|c| !matches!(c, std::path::Component::Normal(_)))
        {
            return Err(format!("unsafe license-file in {}", package.name).into());
        }
        names.insert(file.clone());
    }
    let mut result = Vec::new();
    for name in names {
        let text = read_text(&package.dir.join(name))?;
        if !result.contains(&text) {
            result.push(text);
        }
    }
    if result.is_empty() {
        let fallback = FALLBACKS.iter().any(|(name, version, license, _)| {
            *name == package.name && *version == package.version && *license == package.license
        });
        if !fallback {
            return Err(format!(
                "no license text for {} {}; review before shipping it",
                package.name, package.version
            )
            .into());
        }
        result.push(APACHE_2_0.to_owned());
    }
    Ok(result)
}

/// Render the notices. Texts are numbered by first use in name/version order and shared
/// between packages, so the file is stable for a given lock and crate content.
fn render(product: &str, version: &str, entries: &[(Package, Vec<String>)]) -> String {
    let mut numbering: Vec<&str> = Vec::new();
    let mut users: BTreeMap<usize, Vec<String>> = BTreeMap::new();
    let mut listing = String::new();
    for (package, package_texts) in entries {
        let mut ids = Vec::new();
        for text in package_texts {
            let id = numbering
                .iter()
                .position(|seen| seen == text)
                .unwrap_or_else(|| {
                    numbering.push(text);
                    numbering.len() - 1
                })
                + 1;
            users
                .entry(id)
                .or_default()
                .push(format!("{} {}", package.name, package.version));
            ids.push(format!("[{id}]"));
        }
        listing.push_str(&format!(
            "- {} {} ({}) {}\n",
            package.name,
            package.version,
            package.license,
            ids.join(" ")
        ));
    }
    let mut out = format!(
        "THIRD-PARTY NOTICES for {product} {version}\n\n\
         {product} is MIT-licensed (see LICENSE). The Rust crates listed below are the locked,\n\
         non-development, non-build dependencies of the executable from the committed Cargo.lock:\n\
         registry sources only, for the candidate targets declared in family.toml. The list is a\n\
         deliberate superset: it includes procedural-macro helpers and crates that only optional\n\
         features or test builds enable. Each package lists the license texts that follow. This\n\
         file is generated by `cargo xtask notices` and verified by `cargo xtask check`; do not\n\
         edit it by hand.\n\n"
    );
    let notes: Vec<&str> = NATIVE_NOTES
        .iter()
        .filter(|(name, _)| entries.iter().any(|(package, _)| package.name == *name))
        .map(|(_, note)| *note)
        .collect();
    let fallbacks: Vec<String> = FALLBACKS
        .iter()
        .filter(|(name, version, _, _)| {
            entries
                .iter()
                .any(|(p, _)| p.name == *name && p.version == *version)
        })
        .map(|(name, version, _, note)| format!("{name} {version}: {note}"))
        .collect();
    if !notes.is_empty() || !fallbacks.is_empty() {
        out.push_str("## Notes\n\n");
        for note in notes
            .iter()
            .copied()
            .chain(fallbacks.iter().map(String::as_str))
        {
            out.push_str(&format!("- {note}\n"));
        }
        out.push('\n');
    }
    out.push_str(&format!(
        "## Packages ({})\n\n{listing}\n## License texts\n",
        entries.len()
    ));
    for (index, text) in numbering.iter().enumerate() {
        let id = index + 1;
        out.push_str(&format!(
            "\n### [{id}] used by: {}\n\n{text}",
            users[&id].join(", ")
        ));
    }
    out
}

/// Build the notices for the current lock from Cargo metadata and unpacked crate sources.
fn generate(project: &Project) -> Result<String> {
    let targets: Vec<&str> = project.family["compatibility"]["candidate_targets"]
        .as_array()
        .filter(|targets| !targets.is_empty())
        .ok_or("family.toml declares no candidate targets")?
        .iter()
        .map(|target| target.as_str().ok_or("candidate target is not a string"))
        .collect::<std::result::Result<_, _>>()?;
    let mut args = vec!["metadata", "--locked", "--format-version", "1"];
    for target in &targets {
        args.extend(["--filter-platform", target]);
    }
    let metadata: Value = serde_json::from_slice(&capture(&project.root, "cargo", &args, 120)?)?;
    let entries = reachable(&metadata)?
        .into_iter()
        .map(|package| texts(&package).map(|texts| (package, texts)))
        .collect::<Result<Vec<_>>>()?;
    Ok(render(&project.name, &project.version, &entries))
}

/// Both release assets must be regular files at the product root, never links.
pub(crate) fn asset_paths(root: &Path) -> Result<[(&'static str, PathBuf); 2]> {
    let paths = [(LICENSE, root.join(LICENSE)), (FILE, root.join(FILE))];
    for (name, path) in &paths {
        let metadata = fs::symlink_metadata(path)
            .map_err(|_| format!("release notice asset absent: {name}"))?;
        if !metadata.file_type().is_file()
            || metadata.len() == 0
            || metadata.len() > 8 * 1024 * 1024
        {
            return Err(
                format!("release notice asset is not a bounded regular file: {name}").into(),
            );
        }
    }
    Ok(paths)
}

/// Fail unless the committed file equals the freshly generated text.
fn compare(root: &Path, expected: &str) -> Result<()> {
    asset_paths(root)?;
    if fs::read(root.join(FILE))? != expected.as_bytes() {
        return Err(format!("{FILE} is stale: review and run `cargo xtask notices`").into());
    }
    Ok(())
}

/// Verify the committed notices without writing anything.
pub(crate) fn check(project: &Project) -> Result<()> {
    compare(&project.root, &generate(project)?)?;
    println!("notices: {FILE} matches the locked dependency set");
    Ok(())
}

/// Regenerate the committed notices; the diff is reviewed through Git like any source.
pub(crate) fn write(project: &Project) -> Result<()> {
    let text = generate(project)?;
    let path = project.root.join(FILE);
    if fs::symlink_metadata(&path).is_ok_and(|m| !m.file_type().is_file()) {
        return Err(format!("{FILE} must be a regular file").into());
    }
    fs::write(path, text)?;
    println!("notices: wrote {FILE}");
    Ok(())
}

#[cfg(test)]
#[allow(clippy::unwrap_used, reason = "Test assertions fail explicitly")]
mod tests {
    use super::*;
    use serde_json::json;

    fn node(id: &str, deps: &[(&str, Value)]) -> Value {
        json!({"id": id, "deps": deps.iter().map(|(pkg, kind)| json!({"pkg": pkg, "dep_kinds": [{"kind": kind}]})).collect::<Vec<_>>()})
    }
    fn package(id: &str, name: &str, source: Value, dir: &str) -> Value {
        json!({"id": id, "name": name, "version": "1.0.0", "source": source, "license": "MIT",
               "license_file": null, "manifest_path": format!("{dir}/Cargo.toml")})
    }
    fn registry() -> Value {
        json!("registry+https://github.com/rust-lang/crates.io-index")
    }
    fn fixture(root: &str) -> Value {
        json!({
            "resolve": {"root": "root", "nodes": [
                node("root", &[("normal", Value::Null), ("build", json!("build")), ("dev", json!("dev")), ("member", Value::Null)]),
                node("normal", &[("deep", Value::Null), ("deep-dev", json!("dev"))]),
                node("member", &[("via-member", Value::Null)]),
                node("build", &[("only-build", Value::Null)]),
                node("dev", &[("only-dev", Value::Null)]),
                node("deep", &[]), node("deep-dev", &[]), node("via-member", &[]),
                node("only-build", &[]), node("only-dev", &[]),
            ]},
            "packages": [
                package("root", "root", Value::Null, root),
                package("member", "member", Value::Null, root),
                package("normal", "normal", registry(), root),
                package("deep", "deep", registry(), root),
                package("via-member", "via-member", registry(), root),
                package("build", "build", registry(), root),
                package("dev", "dev", registry(), root),
                package("deep-dev", "deep-dev", registry(), root),
                package("only-build", "only-build", registry(), root),
                package("only-dev", "only-dev", registry(), root),
            ],
        })
    }
    fn names(packages: &[Package]) -> Vec<&str> {
        packages.iter().map(|p| p.name.as_str()).collect()
    }
    fn sample(name: &str, version: &str, license: &str, dir: &Path) -> Package {
        Package {
            name: name.into(),
            version: version.into(),
            license: license.into(),
            dir: dir.to_path_buf(),
            license_file: None,
        }
    }

    #[test]
    fn only_normal_registry_edges_ship() {
        let selected = reachable(&fixture("/crates")).unwrap();
        assert_eq!(names(&selected), ["deep", "normal", "via-member"]);
    }
    #[test]
    fn foreign_sources_and_missing_licenses_are_rejected() {
        let mut metadata = fixture("/crates");
        metadata["packages"][2]["source"] = json!("git+https://example.invalid/x");
        assert!(reachable(&metadata).is_err());
        let mut metadata = fixture("/crates");
        metadata["packages"][3]["license"] = Value::Null;
        assert!(reachable(&metadata).is_err());
    }
    #[test]
    fn license_files_are_found_normalized_and_deduplicated() {
        let dir = tempfile::tempdir().unwrap();
        fs::write(dir.path().join("LICENSE-MIT"), "MIT text\r\n\r\n").unwrap();
        fs::write(dir.path().join("LICENSE-APACHE"), "Apache text\n").unwrap();
        fs::write(dir.path().join("COPYING"), "MIT text\n").unwrap();
        fs::write(dir.path().join("README.md"), "not a license").unwrap();
        fs::create_dir(dir.path().join("LICENSES")).unwrap();
        let found = texts(&sample("x", "1.0.0", "MIT OR Apache-2.0", dir.path())).unwrap();
        // File-name order (COPYING, LICENSE-APACHE, LICENSE-MIT); the duplicate MIT text is dropped.
        assert_eq!(found, ["MIT text\n", "Apache text\n"]);
    }
    #[test]
    fn missing_text_fails_unless_exactly_reviewed() {
        let dir = tempfile::tempdir().unwrap();
        assert!(texts(&sample("unknown", "1.0.0", "MIT", dir.path())).is_err());
        assert!(texts(&sample("rmcp", "3.4.1", "Apache-2.0", dir.path())).is_err());
        assert!(texts(&sample("rmcp", "3.4.0", "MIT", dir.path())).is_err());
        let found = texts(&sample("rmcp", "3.4.0", "Apache-2.0", dir.path())).unwrap();
        assert!(found[0].contains("Apache License"));
    }
    #[test]
    fn oversized_non_utf8_and_unsafe_files_are_rejected() {
        let dir = tempfile::tempdir().unwrap();
        fs::write(dir.path().join("LICENSE"), [0xff, 0xfe]).unwrap();
        assert!(texts(&sample("x", "1.0.0", "MIT", dir.path())).is_err());
        fs::write(dir.path().join("LICENSE"), vec![b'a'; 256 * 1024 + 1]).unwrap();
        assert!(texts(&sample("x", "1.0.0", "MIT", dir.path())).is_err());
        fs::remove_file(dir.path().join("LICENSE")).unwrap();
        let mut escaping = sample("x", "1.0.0", "MIT", dir.path());
        escaping.license_file = Some("../LICENSE".into());
        assert!(texts(&escaping).is_err());
    }
    #[test]
    fn rendering_is_deterministic_and_shares_texts() {
        let dir = tempfile::tempdir().unwrap();
        let entries = vec![
            (
                sample("a", "1.0.0", "MIT", dir.path()),
                vec!["T1\n".to_owned()],
            ),
            (
                sample("b", "2.0.0", "MIT", dir.path()),
                vec!["T1\n".to_owned(), "T2\n".to_owned()],
            ),
            (
                sample("libsqlite3-sys", "0.1.0", "MIT", dir.path()),
                vec!["T2\n".to_owned()],
            ),
        ];
        let first = render("agent-test", "0.1.0", &entries);
        assert_eq!(first, render("agent-test", "0.1.0", &entries));
        assert!(first.contains("## Packages (3)"));
        assert!(first.contains("- a 1.0.0 (MIT) [1]\n- b 2.0.0 (MIT) [1] [2]\n"));
        assert!(first.contains("### [1] used by: a 1.0.0, b 2.0.0\n\nT1\n"));
        assert!(first.contains("### [2] used by: b 2.0.0, libsqlite3-sys 0.1.0\n\nT2\n"));
        assert_eq!(first.matches("\nT1\n").count(), 1);
        assert!(first.contains("public domain"));
        assert!(!first.contains(dir.path().to_str().unwrap()));
    }
    #[test]
    fn drift_missing_and_linked_assets_fail() {
        let dir = tempfile::tempdir().unwrap();
        assert!(compare(dir.path(), "x\n").is_err());
        fs::write(dir.path().join(LICENSE), "MIT\n").unwrap();
        fs::write(dir.path().join(FILE), "old\n").unwrap();
        assert!(compare(dir.path(), "new\n").is_err());
        compare(dir.path(), "old\n").unwrap();
        fs::remove_file(dir.path().join(FILE)).unwrap();
        fs::write(dir.path().join("real"), "old\n").unwrap();
        #[cfg(unix)]
        {
            std::os::unix::fs::symlink("real", dir.path().join(FILE)).unwrap();
            assert!(compare(dir.path(), "old\n").is_err());
        }
    }
}
